package main

import (
	"html"
	"fmt"
)

func testSanitization() {
	tests := []string{
		"Hello, World!",                     // Normal message
		"<script>alert('XSS')</script>",     // XSS attempt
		"Line\nBreak",                       // Line break
		"Tab\tCharacter",                    // Tab character
		"Special chars: & < > \" ' ",       // Special characters
	}

	for _, msg := range tests {
		sanitized := html.EscapeString(msg)
		fmt.Printf("Original: %s\nSanitized: %s\n\n", msg, sanitized)
	}
}

func main() {
	testSanitization()
}

