package main

import (
	"html"
	"testing"
)

func BenchmarkEscapeString(b *testing.B) {
	msg := "<script>alert('XSS')</script>"
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		html.EscapeString(msg)
	}
}

func BenchmarkWithoutEscape(b *testing.B) {
	msg := "<script>alert('XSS')</script>"
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		// Using a simple string copy instead of escape
		_ = msg
	}
}
